/**
 * Plug-in ("balcony") solar output and value per state.
 *
 * Output per kW comes from src/data/plugin-solar-model.json, generated by
 * scripts/plugin_solar_model.py: the same PVWatts v8 model and NASA weather as
 * the rooftop figures, but for the mounting positions plug-in kits really get.
 */

import model from "@/data/plugin-solar-model.json";
import { rateUsd, type StateEnergy } from "@/lib/energy";

export type Mounting = "tilted" | "vertical_s" | "vertical_ew";

export const MOUNTING_LABEL: Record<Mounting, string> = {
  tilted: "On a stand, facing south, 30° tilt",
  vertical_s: "Flat on a south-facing railing or wall",
  vertical_ew: "Flat on an east- or west-facing railing",
};

interface ModelEntry {
  city: string;
  tilted: { kwhPerKwYear: number; monthlyKwhPerKw: number[] };
  vertical_s: { kwhPerKwYear: number; monthlyKwhPerKw: number[] };
  vertical_ew: { kwhPerKwYear: number; monthlyKwhPerKw: number[] };
}

const STATES_MODEL = (model as { states: Record<string, ModelEntry> }).states;

export function pluginModel(abbr: string): ModelEntry {
  const m = STATES_MODEL[abbr];
  if (!m) throw new Error(`No plug-in solar model for ${abbr}`);
  return m;
}

/** Reference kit used for headline figures: 800 W of panels (a common US kit size). */
export const REFERENCE_KIT_W = 800;

/**
 * Yearly output, bill value and simple payback for a plug-in kit.
 * Value assumes every kWh is used in the home and offsets a kWh bought at the
 * state's average residential price: an upper bound, because power the home
 * doesn't use at that moment flows to the grid, usually uncredited.
 */
export function pluginFigures(s: StateEnergy, kitW = REFERENCE_KIT_W, mounting: Mounting = "tilted", kitPriceUsd?: number) {
  const m = pluginModel(s.abbr)[mounting];
  const kwhYear = (m.kwhPerKwYear * kitW) / 1000;
  const valueYear = kwhYear * rateUsd(s);
  return {
    kwhYear,
    kwhMonthAvg: kwhYear / 12,
    valueYear,
    paybackYears: kitPriceUsd && valueYear > 0 ? kitPriceUsd / valueYear : null,
    monthlyKwh: m.monthlyKwhPerKw.map((v) => (v * kitW) / 1000),
  };
}
